CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE IF NOT EXISTS hospitals (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, code text UNIQUE NOT NULL, address text, phone text, created_at timestamptz DEFAULT now(), updated_at timestamptz DEFAULT now(), is_active boolean DEFAULT true);
CREATE TABLE IF NOT EXISTS departments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), hospital_id uuid REFERENCES hospitals(id), name text NOT NULL, created_at timestamptz DEFAULT now(), updated_at timestamptz DEFAULT now(), is_active boolean DEFAULT true);
CREATE TABLE IF NOT EXISTS wards (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), department_id uuid REFERENCES departments(id), name text NOT NULL, floor text, capacity int, created_at timestamptz DEFAULT now(), updated_at timestamptz DEFAULT now(), is_active boolean DEFAULT true);
CREATE TABLE IF NOT EXISTS rooms (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), ward_id uuid REFERENCES wards(id), room_number text NOT NULL, created_at timestamptz DEFAULT now(), updated_at timestamptz DEFAULT now(), is_active boolean DEFAULT true);
CREATE TABLE IF NOT EXISTS beds (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), room_id uuid REFERENCES rooms(id), bed_number text NOT NULL, status text CHECK(status IN ('available','occupied','maintenance')) DEFAULT 'available', created_at timestamptz DEFAULT now(), updated_at timestamptz DEFAULT now(), is_active boolean DEFAULT true);
CREATE TABLE IF NOT EXISTS roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text UNIQUE NOT NULL, description text);
INSERT INTO roles(name,description) VALUES ('nurse_admin','Administrator'),('charge_nurse','Charge nurse'),('staff_nurse','Staff nurse') ON CONFLICT DO NOTHING;
CREATE TABLE IF NOT EXISTS users (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), username text UNIQUE NOT NULL, password_hash text NOT NULL, role_id uuid REFERENCES roles(id), last_login_at timestamptz, failed_attempts int DEFAULT 0, locked_until timestamptz, created_at timestamptz DEFAULT now(), updated_at timestamptz DEFAULT now(), is_active boolean DEFAULT true);
CREATE TABLE IF NOT EXISTS nurses (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid UNIQUE REFERENCES users(id), employee_no text UNIQUE, full_name text NOT NULL, license_no text, phone text, email text, created_at timestamptz DEFAULT now(), updated_at timestamptz DEFAULT now(), is_active boolean DEFAULT true);
CREATE TABLE IF NOT EXISTS permissions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), code text UNIQUE NOT NULL, description text);
CREATE TABLE IF NOT EXISTS role_permissions (role_id uuid REFERENCES roles(id), permission_id uuid REFERENCES permissions(id), PRIMARY KEY(role_id,permission_id));
CREATE TABLE IF NOT EXISTS nurse_ward_assignments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), nurse_id uuid REFERENCES nurses(id), ward_id uuid REFERENCES wards(id), start_date date NOT NULL, end_date date);
CREATE TABLE IF NOT EXISTS sessions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid REFERENCES users(id), token_hash text NOT NULL, device_info text, ip_address inet, expires_at timestamptz, revoked_at timestamptz);
CREATE TABLE IF NOT EXISTS clinicians (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), full_name text NOT NULL, specialty text, license_no text);
CREATE TABLE IF NOT EXISTS patients (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), patient_no text UNIQUE NOT NULL, full_name text NOT NULL, date_of_birth date, gender text, contact_encrypted text, address_encrypted text, emergency_contact_encrypted text, blood_group text, created_at timestamptz DEFAULT now(), updated_at timestamptz DEFAULT now(), created_by uuid REFERENCES users(id), updated_by uuid REFERENCES users(id), is_active boolean DEFAULT true, deleted_at timestamptz);
CREATE TABLE IF NOT EXISTS admissions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), patient_id uuid REFERENCES patients(id), ward_id uuid REFERENCES wards(id), room_id uuid REFERENCES rooms(id), bed_id uuid REFERENCES beds(id), admitting_clinician_id uuid REFERENCES clinicians(id), admission_datetime timestamptz NOT NULL DEFAULT now(), diagnosis text, clinical_history text, status text CHECK(status IN ('admitted','discharged','transferred')) DEFAULT 'admitted', assigned_nurse_id uuid REFERENCES nurses(id), created_at timestamptz DEFAULT now(), updated_at timestamptz DEFAULT now());
CREATE UNIQUE INDEX IF NOT EXISTS one_active_admission_per_bed ON admissions(bed_id) WHERE status='admitted' AND bed_id IS NOT NULL;
CREATE TABLE IF NOT EXISTS allergies (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), patient_id uuid REFERENCES patients(id), allergen text NOT NULL, reaction text, severity text, verified_by uuid REFERENCES nurses(id), verified_at timestamptz);
CREATE TABLE IF NOT EXISTS shifts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), ward_id uuid REFERENCES wards(id), shift_type text CHECK(shift_type IN ('morning','evening','night')), start_time time, end_time time, shift_date date);
CREATE TABLE IF NOT EXISTS shift_nurses (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), shift_id uuid REFERENCES shifts(id), nurse_id uuid REFERENCES nurses(id), role_in_shift text);
CREATE TABLE IF NOT EXISTS shift_patient_assignments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), shift_id uuid REFERENCES shifts(id), nurse_id uuid REFERENCES nurses(id), admission_id uuid REFERENCES admissions(id));
CREATE TABLE IF NOT EXISTS sbar_reports (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), admission_id uuid REFERENCES admissions(id), author_nurse_id uuid REFERENCES nurses(id), shift_id uuid REFERENCES shifts(id), status text CHECK(status IN ('draft','sent','acknowledged','finalized')) DEFAULT 'draft', situation text, background text, assessment text, recommendation text, created_at timestamptz DEFAULT now(), sent_at timestamptz);
CREATE TABLE IF NOT EXISTS sbar_recipients (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), sbar_id uuid REFERENCES sbar_reports(id), receiving_nurse_id uuid REFERENCES nurses(id), acknowledged_at timestamptz, acknowledgement_note text);
CREATE TABLE IF NOT EXISTS sbar_versions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), sbar_id uuid REFERENCES sbar_reports(id), version_no int, content_json jsonb, edited_by uuid REFERENCES users(id), edited_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS vital_signs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), admission_id uuid REFERENCES admissions(id), recorded_by uuid REFERENCES nurses(id), recorded_at timestamptz DEFAULT now(), systolic_bp numeric, diastolic_bp numeric, heart_rate numeric, respiratory_rate numeric, temperature numeric, spo2 numeric, pain_score numeric, blood_glucose numeric);
CREATE TABLE IF NOT EXISTS medication_orders (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), admission_id uuid REFERENCES admissions(id), drug_name text NOT NULL, order_details text NOT NULL, route text, frequency text, start_datetime timestamptz, stop_datetime timestamptz, ordering_clinician_id uuid REFERENCES clinicians(id), verified_by uuid REFERENCES nurses(id), status text CHECK(status IN ('active','stopped','completed')) DEFAULT 'active');
CREATE TABLE IF NOT EXISTS medication_schedules (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), order_id uuid REFERENCES medication_orders(id), scheduled_datetime timestamptz NOT NULL);
CREATE TABLE IF NOT EXISTS medication_administrations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), schedule_id uuid REFERENCES medication_schedules(id), status text CHECK(status IN ('given','not_given','delayed','refused')), administered_by uuid REFERENCES nurses(id), administered_at timestamptz DEFAULT now(), allergy_check_done boolean DEFAULT false, order_check_done boolean DEFAULT false, omission_reason text, delay_reason text);
CREATE TABLE IF NOT EXISTS care_plans (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), admission_id uuid REFERENCES admissions(id), problem text, goal text, interventions text, status text DEFAULT 'active', created_by uuid REFERENCES users(id));
CREATE TABLE IF NOT EXISTS nursing_tasks (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), admission_id uuid REFERENCES admissions(id), care_plan_id uuid REFERENCES care_plans(id), category text CHECK(category IN ('hygiene','mobility','wound_care','monitoring','other')), title text NOT NULL, priority text DEFAULT 'normal', status text DEFAULT 'pending', assigned_nurse_id uuid REFERENCES nurses(id), due_datetime timestamptz, completed_at timestamptz, completed_by uuid REFERENCES nurses(id), created_at timestamptz DEFAULT now(), updated_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS wound_care_records (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), admission_id uuid REFERENCES admissions(id), site text, description text, dressing_details text, recorded_by uuid REFERENCES nurses(id), recorded_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS intake_output_records (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), admission_id uuid REFERENCES admissions(id), type text CHECK(type IN ('intake','output')), item text, amount_ml numeric, recorded_by uuid REFERENCES nurses(id), recorded_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS nursing_notes (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), admission_id uuid REFERENCES admissions(id), author_nurse_id uuid REFERENCES nurses(id), observation text, intervention text, patient_response text, follow_up text, status text CHECK(status IN ('draft','finalized')) DEFAULT 'draft', finalized_at timestamptz);
CREATE TABLE IF NOT EXISTS note_addenda (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), note_id uuid REFERENCES nursing_notes(id), addendum_text text NOT NULL, added_by uuid REFERENCES users(id), added_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS shift_handover_checklists (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), shift_id uuid REFERENCES shifts(id), outgoing_nurse_id uuid REFERENCES nurses(id), incoming_nurse_id uuid REFERENCES nurses(id), completed_at timestamptz);
CREATE TABLE IF NOT EXISTS shift_handover_items (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), checklist_id uuid REFERENCES shift_handover_checklists(id), item_label text, is_done boolean DEFAULT false);
CREATE TABLE IF NOT EXISTS pending_task_transfers (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), task_id uuid REFERENCES nursing_tasks(id), from_nurse_id uuid REFERENCES nurses(id), to_nurse_id uuid REFERENCES nurses(id), shift_id uuid REFERENCES shifts(id), transferred_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS discharge_plans (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), admission_id uuid UNIQUE REFERENCES admissions(id), status text CHECK(status IN ('planned','assessment_in_progress','checklist_complete','awaiting_clinician_approval','approved','discharged','cancelled')) DEFAULT 'planned', planned_discharge_date date, readiness_status text, destination text, responsible_clinician_id uuid REFERENCES clinicians(id), discharging_nurse_id uuid REFERENCES nurses(id), discharge_datetime timestamptz, finalized_at timestamptz, finalized_by uuid REFERENCES users(id), created_at timestamptz DEFAULT now(), updated_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS discharge_assessments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), plan_id uuid UNIQUE REFERENCES discharge_plans(id), clinical_condition text, nursing_assessment text, mobility_status text, self_care_status text, patient_family_understanding text, followup_needs text, pending_investigations text, assessed_by uuid REFERENCES nurses(id), assessed_at timestamptz);
CREATE TABLE IF NOT EXISTS discharge_checklist_templates (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), ward_id uuid REFERENCES wards(id), item_label text NOT NULL, is_mandatory boolean DEFAULT true, sort_order int DEFAULT 0);
CREATE TABLE IF NOT EXISTS discharge_checklist_items (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), plan_id uuid REFERENCES discharge_plans(id), template_id uuid REFERENCES discharge_checklist_templates(id), item_label text NOT NULL, is_mandatory boolean DEFAULT true, is_done boolean DEFAULT false, done_by uuid REFERENCES nurses(id), done_at timestamptz, note text);
CREATE TABLE IF NOT EXISTS discharge_education_records (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), plan_id uuid REFERENCES discharge_plans(id), topic text, teaching_method text, nurse_id uuid REFERENCES nurses(id), educated_at timestamptz, recipient text CHECK(recipient IN ('patient','caregiver')), understanding_level text CHECK(understanding_level IN ('understood','partial','needs_reinforcement')), note text);
CREATE TABLE IF NOT EXISTS discharge_medication_reconciliation (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), plan_id uuid REFERENCES discharge_plans(id), order_id uuid REFERENCES medication_orders(id), reconciliation_status text CHECK(reconciliation_status IN ('matched','discrepancy')), discrepancy_note text, reviewed_by_clinician_id uuid REFERENCES clinicians(id), reviewed_at timestamptz, patient_educated boolean DEFAULT false, educated_by uuid REFERENCES nurses(id));
CREATE TABLE IF NOT EXISTS followup_appointments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), plan_id uuid REFERENCES discharge_plans(id), department_or_specialist text, appointment_date date, location text, notes text);
CREATE TABLE IF NOT EXISTS referrals (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), plan_id uuid REFERENCES discharge_plans(id), referred_to text, reason text, referral_date date, status text);
CREATE TABLE IF NOT EXISTS pending_results_followups (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), plan_id uuid REFERENCES discharge_plans(id), test_name text, responsible_team text, due_date date, status text);
CREATE TABLE IF NOT EXISTS home_care_requirements (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), plan_id uuid REFERENCES discharge_plans(id), requirement_type text, provider text, details text);
CREATE TABLE IF NOT EXISTS discharge_acknowledgements (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), plan_id uuid REFERENCES discharge_plans(id), acknowledged_by_name text, relationship text CHECK(relationship IN ('patient','caregiver')), acknowledged_at timestamptz, signature_ref text);
CREATE TABLE IF NOT EXISTS discharge_approvals (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), plan_id uuid REFERENCES discharge_plans(id), clinician_id uuid REFERENCES clinicians(id), approved_at timestamptz, approval_note text);
CREATE TABLE IF NOT EXISTS discharge_summaries (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), plan_id uuid REFERENCES discharge_plans(id), pdf_path text, generated_by uuid REFERENCES users(id), generated_at timestamptz DEFAULT now(), version_no int);
CREATE TABLE IF NOT EXISTS audit_logs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid REFERENCES users(id), action text NOT NULL, table_name text NOT NULL, record_id uuid, old_value_json jsonb, new_value_json jsonb, ip_address inet, device_info text, created_at timestamptz DEFAULT now());
CREATE OR REPLACE FUNCTION prevent_audit_mutation() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'audit_logs is append-only'; END $$;
DROP TRIGGER IF EXISTS audit_no_update ON audit_logs;
CREATE TRIGGER audit_no_update BEFORE UPDATE OR DELETE ON audit_logs FOR EACH ROW EXECUTE FUNCTION prevent_audit_mutation();
CREATE TABLE IF NOT EXISTS report_exports (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), report_type text, generated_by uuid REFERENCES users(id), parameters_json jsonb, file_path text, generated_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS notifications (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), recipient_nurse_id uuid REFERENCES nurses(id), type text, message text, is_read boolean DEFAULT false, created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS backup_logs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), started_at timestamptz, completed_at timestamptz, status text, location text);
CREATE INDEX IF NOT EXISTS idx_admissions_patient ON admissions(patient_id);
CREATE INDEX IF NOT EXISTS idx_sbar_admission ON sbar_reports(admission_id);
CREATE INDEX IF NOT EXISTS idx_vitals_admission ON vital_signs(admission_id);
CREATE INDEX IF NOT EXISTS idx_tasks_status ON nursing_tasks(status);
CREATE INDEX IF NOT EXISTS idx_med_schedule ON medication_schedules(scheduled_datetime);
CREATE INDEX IF NOT EXISTS idx_discharge_status ON discharge_plans(status);
CREATE INDEX IF NOT EXISTS idx_audit_record_time ON audit_logs(table_name,record_id,created_at);
